// isPathTraversal checks if the input contains path traversal attempts by resolving the path
// against a base directory. It ensures the resolved path is within the allowed scope.
func isPathTraversal(input string, baseDir string) bool {
	resolved, err := filepath.EvalSymlinks(filepath.Join(baseDir, input))
	if err != nil {
		return true
	}
	return !strings.HasPrefix(resolved, baseDir)
