// safeExecute executes a command only if it is in the allowed command list, avoiding shell interpretation.
func safeExecute(command string, args ...string) error {
	allowedCommands := map[string]bool{"ls": true, "grep": true, "find": true, "cat": true, "echo": true}
	if !allowedCommands[command] {
		return fmt.Errorf("command not allowed")
	}
	cmd := exec.Command(command, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// isValidFilePath checks if the input is a valid file path within the specified base directory.
func isValidFilePath(input string, baseDir string) bool {
	resolved := filepath.Clean(filepath.Join(baseDir, input))
	return strings.HasPrefix(resolved, baseDir)
}

// isUnicodeSafe checks if all characters in the input are within a safe Unicode range.
func isUnicodeSafe(input string) bool {
	for _, r := range input {
		if !unicode.IsPrint(r) || !unicode.IsLetter(r) && !unicode.IsDigit(r) && !unicode.IsPunct(r) {
			return false
		}
	}
	return true
}

// validateAndSanitizeInput validates and sanitizes user input for secure file path and command execution.
func validateAndSanitizeInput(input string, baseDir string) error {
	// Check for input length limits
	if len(input) > 256 {
		return fmt.Errorf("input length exceeds maximum allowed")
	}

	// Check for Unicode safety
	if !isUnicodeSafe(input) {
		return fmt.Errorf("invalid Unicode character")
	}

	// Check for path traversal
	if isPathTraversal(input, baseDir) {
		return fmt.Errorf("path traversal detected")
	}

	// Check for invalid characters
	if strings.ContainsAny(input, `*?"<>|`) {
		return fmt.Errorf("invalid characters found")
	}

	// Validate file path against base directory
	if !isValidFilePath(input, baseDir) {
		return fmt.Errorf("file path is outside allowed directory")
	}

	return nil
}

