	fileInfo, err := os.Stat(allowedDirReal)
	if err != nil {
		return "", fmt.Errorf("allowed directory does not exist: %v", err)
	}
	if !fileInfo.IsDir() {
		return "", fmt.Errorf("allowed directory is not a directory")
	}

	// Step 4: Resolve the input path to an absolute path
	inputAbsPath, err := filepath.Abs(dirPath)
	if err != nil {
		return "", fmt.Errorf("failed to resolve input path: %v", err)
	}

	// Step 5: Ensure the input path is within the allowed directory
	if !strings.HasPrefix(inputAbsPath, allowedDirReal) {
		return "", fmt.Errorf("input path is outside the allowed directory")
	}

	// Step 6: Check if the input path is a directory
	fileInfo, err = os.Stat(inputAbsPath)
	if err != nil {
		return "", fmt.Errorf("input path does not exist: %v", err)
	}
	if !fileInfo.IsDir() {
		return "", fmt.Errorf("input path is not a directory")
	}

	return inputAbsPath, nil
}

