func ValidateDomain(domain, parent string) bool {
    domainParts := strings.Split(domain, ".")
    parentParts := strings.Split(parent, ".")

    if len(domainParts) == len(parentParts) {
        // Check if the domain is exactly the same as the parent
        for i := range domainParts {
            if domainParts[i] != parentParts[i] {
                return false
            }
        }
        return false // Return false if it's the same domain
    }

    if len(domainParts) < len(parentParts) {
        return false
    }

    for i := 0; i < len(parentParts); i++ {
        if domainParts[len(domainParts)-len(parentParts)+i] != parentParts[i] {
            return false
        }
    }

    return true
}

