	if err != nil {
		return 0 // Return 0 in case of decoding error
	}

	// Parse the decoded data as JSON
	var infections []int
	if err := json.Unmarshal(decoded, &infections); err != nil {
		return 0 // Return 0 in case of JSON parsing error
	}

	// Sum the first 10 days' infections
