    char* empty_result = malloc(1);
    empty_result[0] = '\0';
    char dir_realpath[1024];
    if (realpath(dir_path, dir_realpath) == NULL) {
        return empty_result;  // Invalid directory path, return an empty string
    }

    // Construct the full file path
