// CreateTarArchive creates a tar archive from the given file paths and saves it to the specified output file.
// It ensures that all file paths are relative, not absolute, and do not contain path traversal components.
func CreateTarArchive(filePaths []string, outputFile string) error {
    // Validate the output file path
    if strings.HasPrefix(outputFile, "/") {
        return errors.New("output file cannot be an absolute path")
    }

    normalizedOutput := filepath.Clean(outputFile)
    if strings.Contains(normalizedOutput, "..") {
        return errors.New("output file path contains '..'")
    }

    // Check if the output file is a symlink
    fileInfo, err := os.Lstat(outputFile)
    if err != nil {
        return err
    }

    if fileInfo.Mode()&os.ModeSymlink != 0 {
        return errors.New("output file cannot be a symlink")
    }

    // Validate each file path
    for _, filePath := range filePaths {
        if strings.HasPrefix(filePath, "/") {
            return errors.New("file path cannot be an absolute path")
        }

        normalizedPath := filepath.Clean(filePath)
        if strings.Contains(normalizedPath, "..") {
            return errors.New("file path contains '..'")
        }

        // Check if the file exists
        _, err := os.Stat(filePath)
        if err != nil {
            return err
        }
    }

    // Create the output file
    outFile, err := os.Create(outputFile)
    if err != nil {
        return err
    }
    defer outFile.Close()

    // Create a tar writer
    tarWriter := tar.NewWriter(outFile)
    defer tarWriter.Close()

    // Add each file to the tar archive
    for _, filePath := range filePaths {
        file, err := os.Open(filePath)
        if err != nil {
            return err
        }
        defer file.Close()

        fileInfo, err := file.Stat()
        if err != nil {
            return err
        }

        header := &tar.Header{
            Name: filePath,
            Size: fileInfo.Size(),
        }

        if err := tarWriter.WriteHeader(header); err != nil {
            return err
        }

        if _, err := io.Copy(tarWriter, file); err != nil {
            return err
        }
    }

    return nil
}

