def secure_key_removal(my_dict, key, allowed_keys=None, lock=None):
    """
    Securely removes a key from a dictionary with input validation, error handling, and thread safety.

    Parameters:
    - my_dict (dict): The dictionary from which to remove the key.
    - key (str): The key to be removed.
    - allowed_keys (list, optional): A list of keys that are permitted for removal. Defaults to None.
    - lock (threading.Lock, optional): A lock for thread-safe operations. Defaults to None.

    Returns:
    - None
    """
    if allowed_keys is None:
        allowed_keys = []

    if key not in allowed_keys:
        raise ValueError(f"Key '{key}' is not allowed for removal.")

    if lock:
        with lock:
            try:
                value = my_dict.pop(key, None)
                if value is None:
                    raise KeyError(f"Key '{key}' not found in the dictionary.")
            except KeyError as e:
                raise RuntimeError(f"Failed to remove key '{key}': {str(e)}")
