// ValidateDirectory checks if the given path is a valid directory and not a symlink.
func ValidateDirectory(dirPath string) bool {
    fileInfo, err := os.Lstat(dirPath)
    if err != nil {
        if os.IsNotExist(err) {
            return false // Path does not exist
        }
        return false // Other errors (e.g., permission denied)
