int validate_domain(const char *domain) {
    if (domain == NULL || strlen(domain) == 0) {
        return 0;
    }

    // Check for invalid characters (only alphanumeric and dots)
    for (int i = 0; i < strlen(domain); i++) {
        if (!isalnum(domain[i]) && domain[i] != '.') {
            return 0;
        }
    }

    // Check for consecutive dots
    for (int i = 0; i < strlen(domain) - 1; i++) {
        if (domain[i] == '.' && domain[i + 1] == '.') {
            return 0;
        }
    }

    // Check for leading or trailing dot
    if (domain[0] == '.' || domain[strlen(domain) - 1] == '.') {
        return 0;
    }

    // Split into labels and check for consecutive hyphens
    char *domain_copy = strdup(domain);
    char *label = strtok(domain_copy, ".");
    while (label != NULL) {
        // Check for invalid characters in the label
        for (int i = 0; i < strlen(label); i++) {
            if (!isalnum(label[i]) && label[i] != '-') {
                free(domain_copy);
                return 0;
            }
        }

        // Check for leading or trailing hyphen
        if (label[0] == '-' || label[strlen(label) - 1] == '-') {
            free(domain_copy);
            return 0;
        }

        // Check for consecutive hyphens
        for (int i = 0; i < strlen(label) - 1; i++) {
            if (label[i] == '-' && label[i + 1] == '-') {
                free(domain_copy);
                return 0;
            }
        }

        label = strtok(NULL, ".");
    }

    free(domain_copy);
    return 1;
}

