// GetUserInfo retrieves user information from the database using a parameterized query.
// It returns an empty string if no user is found or an error occurs.
func GetUserInfo(db *sql.DB, userID int) string {
    query := "SELECT name, email FROM users WHERE id = ?"
    row := db.QueryRow(query, userID)

    var name, email string
    err := row.Scan(&name, &email)

    if err == sql.ErrNoRows {
        // No user found
        return ""
    } else if err != nil {
        // Some other error occurred
        return ""
    }

    return fmt.Sprintf("Name: %s, Email: %s", name, email)
}

