// HashPassword generates a hash by combining the password and salt, then applying SHA-256.
// The salt length is fixed as per the function signature and must not be modified.
func HashPassword(password string, salt []byte) []byte {
	// Combine password and salt
	data := append([]byte(password), salt...)
	// Compute SHA-256 hash
	hash := sha256.Sum256(data)
	return hash[:]
