import (
	"strings"
	"unicode"
)

func ValidateDomain(domain string) bool {
	// Check for at least one dot
	if strings.Count(domain, ".") < 1 {
		return false
	}

	// Find the last dot
	lastDot := strings.LastIndex(domain, ".")
	tld := domain[lastDot+1:]
	subdomain := domain[:lastDot]

	// Check TLD length and validity
	if len(tld) < 2 || len(tld) > 6 {
		return false
	}
	if !isValidTLD(tld) {
		return false
	}

	// Check subdomain
	if !isValidSubdomain(subdomain) {
		return false
	}

	return true
}

func isValidTLD(tld string) bool {
	for _, c := range tld {
		if !unicode.IsLetter(c) {
			return false
		}
	}
	return true
}

func isValidSubdomain(sub string) bool {
	if sub == "" {
		return false
	}

	if (sub[0] == '-' || sub[0] == '.') || (sub[len(sub)-1] == '-' || sub[len(sub)-1] == '.') {
		return false
	}

	for i := 0; i < len(sub)-1; i++ {
		if sub[i] == '.' && sub[i+1] == '.' {
			return false
		}
	}

	for _, c := range sub {
		if !unicode.IsLetter(c) && !unicode.IsDigit(c) && c != '-' && c != '.' {
			return false
		}
	}

	return true
}

package password

import (
	"regexp"
)

var (
	uppercaseRegex = regexp.MustCompile(`[A-Z]`)
	lowercaseRegex = regexp.MustCompile(`[a-z]`)
	digitRegex     = regexp.MustCompile(`[0-9]`)
	specialRegex   = regexp.MustCompile(`[^a-zA-Z0-9]`)
	spaceRegex     = regexp.MustCompile(` `)
)

// ValidatePassword checks if the given password meets the specified criteria.
// It returns true if the password is valid, false otherwise.
func ValidatePassword(password string) bool {
	// Check length
	if len(password) < 8 {
		return false
	}

	// Check for spaces
	if spaceRegex.MatchString(password) {
		return false
	}

	// Check for at least one uppercase letter
	if !uppercaseRegex.MatchString(password) {
		return false
	}

	// Check for at least one lowercase letter
	if !lowercaseRegex.MatchString(password) {
		return false
	}

	// Check for at least one digit
	if !digitRegex.MatchString(password) {
		return false
	}

	// Check for at least one special character (non-alphanumeric)
	if !specialRegex.MatchString(password) {
		return false
	}

	return true
}

