int main() {
    char dest[10];  // Destination buffer of size 10
    char src[] = "Hello, World!";  // Source string

    // Use strncpy to safely copy
    strncpy(dest, src, sizeof(dest) - 1);  // Leave room for null terminator
    dest[sizeof(dest) - 1] = '\0';  // Ensure null-termination

    printf("Copied string: %s\n", dest);
